import datetime
class Event:
    def __init__(self, name, day):
        self.name = name
        self.day = day
    def when(self):
        return self.day.isoformat()
e = Event("launch", datetime.date(2024, 3, 1))
print(e.when())

import re
class Parser:
    def __init__(self):
        self.pat = re.compile(r"(\w+)=(\w+)")
    def first(self, text):
        m = self.pat.search(text)
        return m.group(1)
p = Parser()
print(p.first("color=red size=big"))

import datetime
class Shift:
    def __init__(self, d):
        self.d = d
    def plus(self, n):
        self.d = self.d + datetime.timedelta(days=n)
        return self
    def iso(self):
        return self.d.isoformat()
s = Shift(datetime.date(2024, 1, 30))
print(s.plus(1).plus(1).iso())

